731	\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
732		\lean{MIPStarRE.QPBT.ffChar_dotProduct_submodule_expect_eq_zero}
733		\leanok
734		\uses{def:dot-product-orthogonal, def:subfield-trace}
735		Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
736		$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
737		$v \notin V^\perp$,
738		\[
739			\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
740		\]
741		where the expectation is over a uniformly random vector $\bu$ in $V$.
742	\end{lemma}
743	\begin{proof}
744		\leanok
745		This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
746		the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
747		on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
748		shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
749		for the expectation, translation invariance of the uniform distribution on
750		$V$ gives
751		$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
752		= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
753		forces $C = 0$.
754	\end{proof}
